import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static int minute(String s) {
        int c = s.indexOf(':');
        return Integer.parseInt(s.substring(0, c)) * 60 + Integer.parseInt(s.substring(c + 1));
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        int[] diff = new int[1441];
        for (int i = 0; i < n; i++) {
            next();
            next();
            // Busy minutes are the closed range [start, end].
            diff[minute(next())]++;
            diff[minute(next()) + 1]--;
        }
        int busy = 0, run = 0;
        for (int t = 0; t < 1440; t++) {
            busy += diff[t];
            run = busy == 0 ? run + 1 : 0;
            if (run >= k) {
                int start = t - k + 1;
                System.out.printf("%02d:%02d%n", start / 60, start % 60);
                return;
            }
        }
        System.out.println(-1);
    }
}

package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func minute(s []byte) int {
	c := bytes.IndexByte(s, ':')
	h, _ := strconv.Atoi(string(s[:c]))
	m, _ := strconv.Atoi(string(s[c+1:]))
	return h*60 + m
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	diff := make([]int, 1441)
	for i := 0; i < n; i++ {
		next()
		next()
		// Busy minutes are the closed range [start, end].
		diff[minute(next())]++
		diff[minute(next())+1]--
	}
	busy, run := 0, 0
	for t := 0; t < 1440; t++ {
		busy += diff[t]
		if busy == 0 {
			run++
		} else {
			run = 0
		}
		if run >= k {
			start := t - k + 1
			fmt.Printf("%02d:%02d\n", start/60, start%60)
			return
		}
	}
	fmt.Println(-1)
}
